import pandas as pd

def clean(df):
    df = df[(df['Quantity'] >= 1) & (df['Quantity'] <= 8) & (df['Price'] >= 0) & (df['Price'] <= 900)]
    category_mapping = {
        'Accesories': 'Accessories',
        'electronics': 'Electronics',
        'Office Suplies': 'Office Supplies'
    }
    df['Category'] = df['Category'].map(category_mapping).fillna(df['Category'])
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    df = df[df['Category'].isin(allowed)]
    return df

def answer(df):
    category_revenue = df.groupby('Category')['Revenue'].sum().reset_index()
    result = {}
    for row in category_revenue:
        category = row['Category']
        total = row['Revenue']
        result[category] = total
    return result
